from solution import fit

def test_examples():
    assert fit('hello world', 8) == 'hello w…'
    assert fit('hello', 5) == 'hello'

def test_wide_boundary():
    assert fit('你好世界', 6) == '你好…'
    assert fit('你好世界', 5) == '你好…'
    assert fit('你好世界', 4) == '你…'

def test_fits_wide():
    assert fit('你好', 4) == '你好'

def test_width_one():
    assert fit('abc', 1) == '…'
    assert fit('a', 1) == 'a'
    assert fit('你', 1) == '…'

def test_combining_stay():
    s = 'e\u0301e\u0301e\u0301'
    assert fit(s, 3) == s
    assert fit(s + 'x', 3) == 'e\u0301e\u0301…'

def test_combining_fits_zero():
    assert fit('abc\u0301d', 3) == 'ab…'
    assert fit('abc\u0301d', 4) == 'abc\u0301d'

def test_zwj():
    s = 'a\u200db\u200dc'
    assert fit(s, 3) == s
    assert fit(s + 'dd', 3) == 'ab\u200d…'[:0] + 'a\u200db\u200d…'

def test_fullwidth_letters():
    assert fit('ＡＢＣ', 5) == 'ＡＢ…'

def test_emoji():
    assert fit('😀😀😀', 5) == '😀😀…'
    assert fit('😀😀😀', 4) == '😀…'
